@r.get("/org/diagram-tokens", tags=["diagrams"])
async def get_tokens(c: RequestContext = Depends(get_ctx)):
    return {"defaults": render.TOKENS["light"], "org": await _org_tokens(c.org_id)}


@r.put("/org/diagram-tokens", tags=["diagrams"])
async def put_tokens(body: S.TokensIn, c: RequestContext = Depends(get_ctx)):
    if not await authz.allowed(c.principal, "org", "manage", str(c.org_id), {"org_id": str(c.org_id)}):
        await audit.record_denial(c, "org.diagram_tokens", "org", c.org_id)
        raise problem(403, "AT-AUTHZ-001", "Forbidden")
    allowed = set(render.TOKENS["light"])
    clean = {k: v for k, v in body.tokens.items() if k in allowed and len(v) < 40 and all(ch not in v for ch in "<>\"';{}")}
    async with unscoped() as conn:
        s = (await conn.execute(select(organizations.c.settings).where(organizations.c.id == c.org_id))).scalar_one() or {}
        s["diagram_tokens"] = clean
        await conn.execute(organizations.update().where(organizations.c.id == c.org_id).values(settings=s))
    async with uow(c) as conn:
        await audit.record(conn, c, "org.diagram_tokens.update", "org", c.org_id, details=clean)
    return {"org": clean}


async def _org_tokens(org_id: uuid.UUID) -> dict[str, str]:
    async with unscoped() as conn:
        s = (await conn.execute(select(organizations.c.settings).where(organizations.c.id == org_id))).scalar_one() or {}
    return s.get("diagram_tokens") or {}


# ------------------------------------------------------------------ webhook ingress (provider-signed, no user token)
@r.post("/webhooks/{org_id}/{project_id}/{connector_id}", tags=["connectors"], include_in_schema=True)
async def webhook(org_id: uuid.UUID, project_id: uuid.UUID, connector_id: uuid.UUID, request: Request):
    body = await request.body()
    try:
        return await webhooks.receive(org_id, project_id, connector_id, {k.lower(): v for k, v in request.headers.items()}, body)
    except webhooks.Rejected as e:
        # identical body for every rejection reason (no oracle); the reason is only in logs/metrics
        raise problem(e.status, "AT-WEBHOOK-001", "Webhook rejected") from None


@r.get("/projects/{project_id}/connectors/{cid}/webhook", tags=["connectors"])
async def webhook_info(cid: uuid.UUID, request: Request, c: RequestContext = Depends(project_ctx)):
    await require(c, "connector", "view")
    conn_row = await connectors.get(c, cid)
    base = str(request.base_url).rstrip("/")
    return {"url": f"{base}/api/v1/webhooks/{c.org_id}/{c.project_id}/{cid}", "kind": conn_row["kind"],
            "enabled": await flags.enabled("connectors.webhooks", c.org_id, c.project_id),
            "signature": {"github": "X-Hub-Signature-256", "gitlab": "X-Gitlab-Token (the webhook secret token)",
                          "taiga": "X-TAIGA-WEBHOOK-SIGNATURE (HMAC-SHA1 with the webhook key)"}.get(
                conn_row["kind"], "X-ArchTwin-Signature + X-ArchTwin-Timestamp"),
            "events": registry.get(conn_row["kind"]).manifest.get("webhooks", ["push"]),
            "recent": await connectors.recent_deliveries(c, cid)}


