async def _arch(c: RequestContext, action: str = "view"):
    await flags.require(c, "module.architecture-graph")
    await require(c, "architecture", action)


@r.get("/projects/{project_id}/architecture", tags=["architecture"])
async def architecture(snapshot_id: uuid.UUID | None = None, at: datetime | None = None, kinds: str | None = None,
                       c: RequestContext = Depends(project_ctx)):
    await _arch(c)
    g = await arch.graph(c, snapshot_id, at)
    if kinds:
        ks = set(kinds.split(","))
        g["nodes"] = {k: n for k, n in g["nodes"].items() if n["kind"] in ks}
        g["edges"] = {k: e for k, e in g["edges"].items() if e["source"] in g["nodes"] and e["target"] in g["nodes"]}
    return g


