# ------------------------------------------------------------------ diagrams
async def _view(c: RequestContext, view_key: str, snapshot_id, full: bool, deps: bool):
    await flags.require(c, "module.architecture-graph", "module.diagram-studio")
    await require(c, "diagram", "view", view_key)
    g = await arch.graph(c, snapshot_id)
    if not g["snapshot"]:
        raise problem(409, "AT-DIAGRAM-001", "No snapshot", "Scan a connector to generate diagrams.")
    async with uow(c) as conn:
        drift_keys = await drift.open_drift_keys(conn, c)
        lay = (await conn.execute(select(diagram_layouts).where(and_(diagram_layouts.c.project_id == c.project_id,
                                                                     diagram_layouts.c.view_key == view_key)))).first()
    try:
        v = views.build_view(g, view_key, drift_keys, full=full, deps=deps)
    except KeyError as e:
        raise not_found("view") from e
    v["snapshot"] = {"id": g["snapshot"]["id"], "version": g["snapshot"]["version"], "manifest_hash": g["snapshot"]["manifest_hash"]}
    v["layout"] = {"overrides": lay.overrides if lay else {}, "revision": lay.revision if lay else 0}
    return v, g


@r.get("/projects/{project_id}/views/{view_key:path}", tags=["diagrams"])
async def get_view(view_key: str, snapshot_id: uuid.UUID | None = None, full: bool = False, deps: bool = False,
                   c: RequestContext = Depends(project_ctx)):
    v, _ = await _view(c, view_key, snapshot_id, full, deps)
    return v


@r.put("/projects/{project_id}/layouts/{view_key:path}", tags=["diagrams"])
async def put_layout(view_key: str, body: S.LayoutIn, c: RequestContext = Depends(project_ctx)):
    await flags.require(c, "module.diagram-studio")
    await require(c, "diagram", "edit", view_key)
    async with uow(c) as conn:
        cur = (await conn.execute(select(diagram_layouts).where(and_(diagram_layouts.c.project_id == c.project_id,
                                                                     diagram_layouts.c.view_key == view_key)).with_for_update())).first()
        if cur and body.revision is not None and body.revision != cur.revision:
            raise problem(412, "AT-REVISION-001", "Layout changed", "Someone else moved elements; reload.")
        ov = {k: {"x": float(v["x"]), "y": float(v["y"])} for k, v in body.overrides.items() if "x" in v and "y" in v}
        if cur:
            await conn.execute(diagram_layouts.update().where(diagram_layouts.c.id == cur.id).values(
                overrides={**cur.overrides, **ov}, revision=cur.revision + 1, updated_by=c.actor_id, updated_at=datetime.now()))
            rev = cur.revision + 1
        else:
            await conn.execute(diagram_layouts.insert().values(id=new_id(), org_id=c.org_id, project_id=c.project_id, view_key=view_key,
                                                               overrides=ov, updated_by=c.actor_id))
            rev = 1
        await audit.record(conn, c, "diagram.layout.update", "diagram", view_key, details={"moved": len(ov)})
    return {"revision": rev}


@r.delete("/projects/{project_id}/layouts/{view_key:path}", tags=["diagrams"])
async def reset_layout(view_key: str, c: RequestContext = Depends(project_ctx)):
    await require(c, "diagram", "reset_layout", view_key)
    async with uow(c) as conn:
        await conn.execute(diagram_layouts.delete().where(and_(diagram_layouts.c.project_id == c.project_id,
                                                               diagram_layouts.c.view_key == view_key)))
        await audit.record(conn, c, "diagram.layout.reset", "diagram", view_key)
    return {"ok": True}


@r.get("/projects/{project_id}/export/{fmt}/{view_key:path}", tags=["diagrams"])
async def export_view(fmt: str, view_key: str, snapshot_id: uuid.UUID | None = None, full: bool = False, deps: bool = False,
                      c: RequestContext = Depends(project_ctx)):
    await require(c, "diagram", "export", view_key)
    v, g = await _view(c, view_key, snapshot_id, full, deps)
    proj = await projects.get_project(c)
    async with uow(c) as conn:
        await audit.record(conn, c, f"diagram.export.{fmt}", "diagram", view_key, details={"snapshot": str(v["snapshot"]["id"])})
    if fmt == "mermaid":
        return PlainTextResponse(dexport.to_mermaid(v), media_type="text/plain; charset=utf-8")
    if fmt == "structurizr":
        return PlainTextResponse(dexport.to_structurizr(g, proj["title"]), media_type="text/plain; charset=utf-8")
    if fmt in ("svg", "html", "lint"):
        lay = render.layout_and_lint(v)
        lint = {"ok": not lay.violations, "violations": lay.violations, "rules_version": "diagram-lint/1.0"}
        if fmt == "lint":
            return lint
        if lay.violations:   # never publish a non-conforming diagram (AT-DIAGRAM_STUDIO-006)
            raise problem(422, "AT-DIAGRAM-LINT", "Diagram failed the conformance linter", extra={"lint": lint})
        svg = render.to_svg(v, lay, await _org_tokens(c.org_id), title=f"{proj['title']} — {v['title']}")
        if fmt == "svg":
            return Response(svg, media_type="image/svg+xml", headers={"X-ArchTwin-Lint": "pass",
                                                                       "X-ArchTwin-Snapshot": v["snapshot"]["manifest_hash"]})
        page = (f"<!doctype html><html><head><meta charset='utf-8'><title>{proj['title']}</title>"
                "<meta http-equiv='Content-Security-Policy' content=\"default-src 'none'; style-src 'unsafe-inline'; img-src data:\">"
                f"</head><body style='margin:0;background:#f5f5f5'>{svg}<!-- snapshot {v['snapshot']['manifest_hash']} lint pass --></body></html>")
        return Response(page, media_type="text/html; charset=utf-8")
    raise not_found("export format")


