@r.post("/projects/{project_id}/documents", status_code=201, tags=["documents"])
async def document_upload(file: UploadFile = File(...), c: RequestContext = Depends(project_ctx)):
    await flags.require(c, "module.document-parsing", "connector.file_upload")
    await require(c, "document", "upload")
    data = await file.read()
    mime, text, parser = await docs.parse_upload(data, file.filename or "upload")
    async with uow(c) as conn:
        did, created = await docs.upsert_document(conn, c, title=(file.filename or "upload")[:200], path=f"uploads/{file.filename}",
                                                  text_body=text, mime=mime, source_kind="upload", connector_id=None, parser=parser)
        await audit.record(conn, c, "document.upload", "document", did, details={"name": file.filename, "mime": mime, "new": created})
    return {"id": did, "created": created, "mime": mime}


