@r.get("/notifications/stream", tags=["notifications"])
async def notifications_stream(request: Request, p: Principal = Depends(principal)):
    c = RequestContext(p, p.org_id)

    async def gen():
        last = None
        while not await request.is_disconnected():
            items = await notify.list_for(c, unread_only=True, limit=20)
            sig = json.dumps([(str(i["id"]), i["occurrences"]) for i in items])
            if sig != last:
                last = sig
                yield {"event": "notifications", "data": json.dumps({"unread": len(items), "items": items}, default=str)}
            await asyncio.sleep(3)
    return EventSourceResponse(gen(), ping=15)


